// Lead Qualification Agent: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const MIN_BUDGET = 300000;
const SENIOR = ['ceo', 'founder', 'director', 'owner', 'head of', 'md', 'manager', 'principal', 'proprietor'];
const NEED = ['automate', 'automation', 'chatbot', 'training', 'workflow', 'ai', 'crm', 'save time', 'whatsapp'];
const URGENT = ['asap', 'urgent', 'this week', 'this month', 'immediately', 'next week'], LATER = ['next year', 'someday', 'just browsing', 'maybe later', 'no rush'];
const budgetOf = t => { let best = 0; const re = /(?:ngn|₦)?\s?(\d[\d,.]*)\s?(k|m|million)?\b/g; let m;
  while ((m = re.exec(t.toLowerCase()))) { let n = Number(m[1].replace(/,/g, '')); n *= m[2] === 'k' ? 1e3 : (m[2] === 'm' || m[2] === 'million') ? 1e6 : 1; best = Math.max(best, n); }
  return best || null; };
const out = [];
for (const l of input) {
  const msg = l.Message || l.message || '', t = msg.toLowerCase(), name = l.Name || l.name || '';
  const b = budgetOf(msg), senior = SENIOR.find(w => t.includes(w)), needs = NEED.filter(w => new RegExp('\\b' + w + '\\b').test(t));
  const s = { budget: b && b >= MIN_BUDGET ? 25 : b ? 10 : 5, authority: senior ? 25 : 8, need: Math.min(25, 10 * needs.length),
              timeline: URGENT.some(w => t.includes(w)) ? 25 : LATER.some(w => t.includes(w)) ? 0 : 12 };
  const total = Object.values(s).reduce((a, x) => a + x, 0);
  const tier = total >= 70 ? 'HOT' : total >= 45 ? 'WARM' : 'COLD', first = name.split(' ')[0];
  const reply = { HOT: `Hi ${first}, thanks for reaching out. I can help with this. Are you free for a 20-minute call today or tomorrow?`,
    WARM: `Hi ${first}, thanks for your message. Could you share your timeline and the process you want to automate?`,
    COLD: `Hi ${first}, thanks for getting in touch! Here's a short guide on where AI automation saves businesses time. Happy to chat whenever you're ready.` }[tier];
  out.push({ route: tier, name, email: l.Email || l.email, source: l.Source || l.source || 'form', score: total, tier,
             budget: b, authority: senior || '', need: needs.join(', '), message: msg, reply });
}
return out.map(json => ({ json }));
